// Potrace units are 2x the 1280x720 canvas with Y flipped.
const TRANSFORM = "translate(0 720) scale(0.5 -0.5)"

// Pen draws each path line-by-line in paint order, P9-Hub style
// (components/ui/hero-journey-svg.tsx): stroke leads, fill fades in as the
// stroke reaches its end, then the temporary stroke fades out — so the final
// frame is exactly the flat artwork, pixel perfect.
//
// Unlike P9-Hub (hundreds of tiny line-art paths, so a small stagger already
// reads as a pen), this artwork is a handful of large flat-fill paths. We
// therefore give every path an ABSOLUTE start time on one sequential
// timeline: path i starts at i * STEP with only a slight overlap into the
// previous stroke, so the scene is genuinely inked one line at a time and
// the full SVG completes with the last path.
const EASE_DRAW = [0.5, 0, 0.15, 1] as const
const DRAW_DUR = 0.55
const STEP = 0.18

const draw: Variants = {
  hidden: { pathLength: 0, fillOpacity: 0, strokeOpacity: 1 },
  show: (cfg: { index: number }) => ({
    pathLength: 1,
    fillOpacity: [0, 0, 1],
    strokeOpacity: [1, 1, 0],
    transition: {
      delay: cfg.index * STEP,
      pathLength: { duration: DRAW_DUR, ease: EASE_DRAW },
      fillOpacity: {
        duration: DRAW_DUR,
        times: [0, 0.75, 1],
        ease: "easeOut",
      },
      strokeOpacity: {
        duration: DRAW_DUR,
        times: [0, 0.6, 1],
        ease: "easeOut",
      },
    },
  }),
}

// Hand-drawn "boil" filter (per camillovisini.com/coding/simulating-hand-drawn-motion-with-svg-filters,
// same as P9-Hub's p9-hand): turbulence displaces the artwork and a seed
// shuffle re-jitters it ~7x/second while visible, so the ink stays alive.
// Reduced motion gets the finished frame with no filter at all.
const BOIL_SEEDS = [7, 13, 29, 44]

export function HeroDoodleRecordingSession({
  drawIn = false,
  className,
  ...props
}: HeroDoodleRecordingSessionProps & { drawIn?: boolean }) {
  /* motion.svg's prop types are stricter than React's SVGProps; reconcile. */
  const svgProps = props as unknown as ComponentProps<typeof motion.svg>
  const reduce = Boolean(useReducedMotion())
  const wrapRef = useRef<HTMLDivElement | null>(null)
  const entered = useInView(wrapRef, { once: true, margin: "-100px" })
  const live = useInView(wrapRef, { margin: "-64px" })
  const noiseRef = useRef<SVGFETurbulenceElement | null>(null)

  /* Boil: shuffle the turbulence seed ~7x/sec while visible. */
  useEffect(() => {
    if (reduce || !live) return
    let i = 0
    const id = window.setInterval(() => {
      i = (i + 1) % BOIL_SEEDS.length
      noiseRef.current?.setAttribute("seed", String(BOIL_SEEDS[i]))
    }, 150)
    return () => window.clearInterval(id)
  }, [reduce, live])

  const svg = (
    <motion.svg
      viewBox="0 0 1280 720"
      role="img"
      aria-label="Hand-drawn studio journey: walking in, recording in the booth, and mixing the take"
      className={className}
      initial={drawIn && !reduce ? "hidden" : false}
      animate={drawIn ? (entered || reduce ? "show" : "hidden") : undefined}
      {...svgProps}
    >
      <defs>
        <filter id="doodle-wobble" x="-5%" y="-5%" width="110%" height="110%">
          <feTurbulence
            ref={noiseRef}
            type="fractalNoise"
            baseFrequency="0.012"
            numOctaves="2"
            seed="7"
            result="noise"
          />
          <feDisplacementMap
            in="SourceGraphic"
            in2="noise"
            scale={reduce ? 0 : 6}
            xChannelSelector="R"
            yChannelSelector="G"
          />
        </filter>
      </defs>
      <g filter={drawIn && !reduce ? "url(#doodle-wobble)" : undefined}>
        {(() => {
          let index = 0
          return LAYERS.map((layer) => (
            <motion.g
              key={layer.id}
              data-layer={layer.id}
              fill={layer.fill}
              transform={TRANSFORM}
            >
              {layer.elements.map((el) => {
                const i = index++
                return (
                  <motion.path
                    key={el.id}
                    data-element={el.id}
                    d={el.d}
                    fill={layer.fill}
                    stroke={drawIn ? layer.fill : undefined}
                    strokeWidth={drawIn ? 1.2 : undefined}
                    strokeLinejoin="round"
                    strokeLinecap="round"
                    variants={drawIn ? draw : undefined}
                    custom={{ index: drawIn && !reduce ? i : 0 }}
                  />
                )
              })}
            </motion.g>
          ))
        })()}
      </g>
    </motion.svg>
  )

  if (!drawIn) return svg
  return (
    <div ref={wrapRef} className={className ? undefined : "contents"}>
      {svg}
    </div>
  )
}

export default HeroDoodleRecordingSession
